update tours set itinerary = '[{"day": 1, "title": {"en": null, "ru": "Tiệm Cafe Đồng Lúa"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/tiem-cafe-dong-lua/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/tiem-cafe-dong-lua/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/tiem-cafe-dong-lua/3.png"], "description": {"en": null, "ru": "Завтрак в кафе, построенном прямо среди рабочих рисовых полей — деревянные веранды и мостки посреди зелени. Рядом пруд с лотосами. Спокойная точка старта перед дорогой к морю."}, "article_slug": "tiem-cafe-dong-lua"}, {"day": 1, "title": {"en": null, "ru": "Католический собор Ванзя"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/sobor-vanzya/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/sobor-vanzya/2.jpg", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/sobor-vanzya/3.png"], "description": {"en": null, "ru": "Неоготический собор с двумя колокольнями — заметен с трассы за несколько километров. Крупная местная католическая община, служба на вьетнамском. Внутри высокие своды и витражи, совсем другая сторона Центрального Вьетнама."}, "article_slug": "sobor-vanzya"}, {"day": 1, "title": {"en": null, "ru": "Вид на остров Хон Нуа"}, "description": {"en": null, "ru": "Смотровая остановка по дороге: открытое море, силуэт острова Хон Нуа и горный берег. Короткая пауза размять ноги и сделать кадр."}}, {"day": 1, "title": {"en": null, "ru": "Маяк Дай Лань"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/mayak-dai-lan-article/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/mayak-dai-lan-article/2.png"], "description": {"en": null, "ru": "Один из старейших действующих маяков Вьетнама, первая башня — 1890 год, французская постройка. Мыс считается одной из самых восточных точек материковой страны. С него видно сразу и бухту с лодками, и открытое море."}, "article_slug": "mayak-dai-lan"}, {"day": 1, "title": {"en": null, "ru": "Дикий пляж Бай Мон"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/plyazh-bay-mon/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/plyazh-bay-mon/2.jpg"], "description": {"en": null, "ru": "Бухта у подножия мыса с маяком: светлый песок, чистая вода, скалы по краям — и ни одного шезлонга, бара или отеля. Мыс закрывает пляж от волн, вода обычно спокойнее, чем на соседних участках."}, "article_slug": "plyazh-bay-mon"}, {"day": 1, "title": {"en": null, "ru": "Обед в Hương Biển Vũng Rô"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/obed-vung-ro/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/obed-vung-ro/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/obed-vung-ro/3.png"], "description": {"en": null, "ru": "Бухта Вунг Ро — защищённая горами гавань с плавучими фермами, где разводят рыбу и лобстеров. Ресторан стоит на берегу, морепродукты берут из этой же воды в тот же день. Выбираете по улову, оплата по факту."}, "article_slug": "obed-vung-ro"}, {"day": 1, "title": {"en": null, "ru": "Буддийский храм"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/buddiyskiy-khram-dai-lan/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/buddiyskiy-khram-dai-lan/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/mayak-dai-lan/buddiyskiy-khram-dai-lan/3.png"], "description": {"en": null, "ru": "Небольшой действующий храм на обратной дороге — без туристических автобусов. Внутри золотая статуя Будды и подношения от местной общины, снаружи ухоженный двор с пагодой. Тихая точка, чтобы выдохнуть после дня в дороге."}, "article_slug": "buddiyskiy-khram-dai-lan"}]'::jsonb
where slug = 'mayak-dai-lan';

update tours set itinerary = '[{"day": 1, "title": {"en": null, "ru": "Капибары и вьетнамский кофе"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/2.jpg", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/3.png"], "description": {"en": null, "ru": "Начинаем день в кафе с капибарами — их можно погладить и покормить, они спокойные и не боятся людей. Параллельно завариваем кофе через традиционный вьетнамский фильтр фин: медленно, как это делают местные."}, "article_slug": "kapibary-i-kofe-nyachang"}, {"day": 1, "title": {"en": null, "ru": "Башня Куанг-Минь"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/3.png"], "description": {"en": null, "ru": "Новая золотая 13-ярусная башня на горе Фыонг Хоанг — одна из самых заметных точек Нячанга. Сверху открывается панорама на весь город, бухту, острова и линию побережья. Подъезжаем на автомобиле, долго идти пешком не нужно."}, "article_slug": "bashnya-kuang-min"}, {"day": 1, "title": {"en": null, "ru": "Пагода Лонгшон"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/1.jpg", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/3.jpg"], "description": {"en": null, "ru": "Главный буддийский храм Нячанга: белая статуя сидящего Будды высотой 24 метра видна из разных точек города. Внутри комплекса — лежащий Будда, действующий храм и монастырь. К верхней части подъезжаем на машине, минуя 152 ступени под солнцем."}, "article_slug": "pagoda-longshon"}, {"day": 1, "title": {"en": null, "ru": "Кафедральный собор Христа-Царя"}, "description": {"en": null, "ru": "Каменный неоготический собор французской колониальной эпохи, построен в 1930-х из грубого серого камня. Витражи, высокая колокольня с часами и совсем не тропическая атмосфера внутри — контраст с остальным маршрутом."}}, {"day": 1, "title": {"en": null, "ru": "Башни По Нагар"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/3.png"], "description": {"en": null, "ru": "Действующий храмовый комплекс древнего Чамского королевства, VII–XIII века — старше большинства построек Вьетнама. Красный кирпич без раствора, резьба по камню и вид на реку Кай. Сюда до сих пор приходят молиться местные."}, "article_slug": "bashni-po-nagar"}, {"day": 1, "title": {"en": null, "ru": "Хон Чонг"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/3.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/1.png"], "description": {"en": null, "ru": "Гранитный мыс с нагромождением валунов, отполированных морем. С камней — лучшая панорама залива, острова Хон Че и гор на материке. Рядом культурный павильон, где иногда играют на традиционных инструментах."}, "article_slug": "hon-chong"}, {"day": 1, "title": {"en": null, "ru": "Музей Александра Йерсена"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/2.png"], "description": {"en": null, "ru": "Дом-музей учёного, который открыл возбудителя чумы и основал в Нячанге Институт Пастера. Личные вещи, приборы, библиотека и фотографии — короткая, но живая история города с европейской стороны. Йерсена во Вьетнаме до сих пор почитают."}, "article_slug": "muzey-aleksandra-yersena"}, {"day": 1, "title": {"en": null, "ru": "Обед в кафе с вертолётом"}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/3.png"], "description": {"en": null, "ru": "Обед в необычном кафе: во дворе стоит настоящий вертолёт, есть пруд с карпами кои и игуаны. Блюда каждый выбирает под себя — заказ оплачивается по факту, не входит в стоимость тура."}, "article_slug": "obed-v-kafe-s-vertoletom"}]'::jsonb
where slug = 'nyachang-avtorskiy';
